import { cleanup, render, screen } from "@testing-library/react";
import { ThemeProvider, THEME_STORAGE_KEY, useTheme, type Theme } from "../src/theme";
import { ThemeToggle } from "../src/ThemeToggle";

/**
 * Controllable matchMedia stub. jsdom does not implement matchMedia,
 * so we provide one whose `matches` we can flip and whose listeners
 * we can notify manually to simulate OS-level scheme changes.
 */
class MatchMediaStub {
  query: string;
  matches: boolean;
  private listeners = new Set<(event: MediaQueryListEvent) => void>();

  constructor(query: string) {
    this.query = query;
  }

  addEventListener(type: "change", listener: (event: MediaQueryListEvent) => void) {
    if (type === "change") this.listeners.add(listener);
  }

  removeEventListener(type: "change", listener: (event: MediaQueryListEvent) => void) {
    if (type === "change") this.listeners.delete(listener);
  }

  /** Simulate the OS switching its color scheme. */
  setMatches(matches: boolean) {
    if (this.matches === matches) return;
    this.matches = matches;
    const event = {
      matches,
      media: this.query,
    } as MediaQueryListEvent;
    for (const listener of [...this.listeners]) listener(event);
  }
}

const QUERY = "(prefers-color-scheme: dark)";
let stub: MatchMediaStub;

beforeEach(() => {
  window.localStorage.clear();
  // Default to light system scheme; tests may flip via setSystemDark(true/false).
  stub = new MatchMediaStub(QUERY);
  stub.matches = false;
  vi.stubGlobal(
    "matchMedia",
    vi.fn((query: string) => {
      expect(query).toBe(QUERY); // provider must use the exact spec query
      return stub as unknown as MediaQueryList;
    }),
  );
});

afterEach(() => {
  cleanup();
  vi.unstubAllGlobals();
  window.localStorage.clear();
});

function setSystemDark(dark: boolean) {
  stub.setMatches(dark);
}

function Probe() {
  const { theme, resolved } = useTheme();
  return (
    <div>
      <span data-testid="theme">{theme}</span>
      <span data-testid="resolved">{resolved}</span>
    </div>
  );
}

function renderWithProvider(ui: React.ReactNode) {
  return render(<ThemeProvider>{ui}</ThemeProvider>);
}

describe("ThemeProvider", () => {
  it("resolves system to light when matchMedia reports a light scheme", () => {
    renderWithProvider(<Probe />);
    expect(screen.getByTestId("theme")).toHaveTextContent("system");
    expect(screen.getByTestId("resolved")).toHaveTextContent("light");
  });

  it("resolves system to dark when matchMedia reports a dark scheme", () => {
    stub.matches = true;
    renderWithProvider(<Probe />);
    expect(screen.getByTestId("resolved")).toHaveTextContent("dark");
  });

  it("flips resolved when the system scheme changes while in system mode", () => {
    renderWithProvider(<Probe />);
    expect(screen.getByTestId("resolved")).toHaveTextContent("light");

    setSystemDark(true);
    expect(screen.getByTestId("resolved")).toHaveTextContent("dark");

    setSystemDark(false);
    expect(screen.getByTestId("resolved")).toHaveTextContent("light");
  });

  it("persists an explicit choice and restores it through a fresh render", () => {
    const first = renderWithProvider(
      <>
        <Probe />
        <ThemeToggle />
      </>,
    );
    expect(screen.getByTestId("resolved")).toHaveTextContent("light");

    // cycle: system -> light -> dark
    screen.getByRole("button").click();
    screen.getByRole("button").click();
    expect(screen.getByTestId("theme")).toHaveTextContent("dark");
    expect(screen.getByTestId("resolved")).toHaveTextContent("dark");
    first.unmount();

    // fresh mount reads the persisted choice back
    renderWithProvider(<Probe />);
    expect(window.localStorage.getItem(THEME_STORAGE_KEY)).toBe("dark");
    expect(screen.getByTestId("theme")).toHaveTextContent("dark");
    expect(screen.getByTestId("resolved")).toHaveTextContent("dark");
  });

  it("ignores later system changes once an explicit choice is made", () => {
    renderWithProvider(<Probe />);
    setSystemDark(true); // still in system mode: follows the change
    expect(screen.getByTestId("resolved")).toHaveTextContent("dark");

    screen.getByRole("button").click(); // explicit "light"
    expect(screen.getByTestId("theme")).toHaveTextContent("light");
    expect(screen.getByTestId("resolved")).toHaveTextContent("light");

    // OS flips again — resolved must not follow
    setSystemDark(false);
    expect(screen.getByTestId("resolved")).toHaveTextContent("light");

    setSystemDark(true);
    expect(screen.getByTestId("resolved")).toHaveTextContent("light");
  });

  it("treats an invalid stored value as system", () => {
    window.localStorage.setItem(THEME_STORAGE_KEY, "sepia" as unknown as Theme);
    renderWithProvider(<Probe />);
    expect(screen.getByTestId("theme")).toHaveTextContent("system");
  });

  it("throws when useTheme is used outside a ThemeProvider", () => {
    const silence = vi.spyOn(console, "error").mockImplementation(() => {});
    expect(() => render(<Probe />)).toThrow(/useTheme/);
    silence.mockRestore();
  });
});
"})
